#!/bin/sh
# Prints the Homebrew cask for mek-desktop <version> (no leading v) from the
# release's .sha256 files in <dir>: what the release workflow pushes to
# prateep-r/homebrew-tap as Casks/mek-desktop.rb.
# Usage: cask.sh <version> <dir>
set -eu

version=${1:?version, e.g. 0.21.2}
dir=${2:?the directory with the .sha256 files}
sum() { cut -d' ' -f1 "$dir/mek-desktop_${version}_darwin_$1.zip.sha256"; }

cat <<CASK
# Generated by cmd/mek-desktop/cask.sh in prateep-r/mek. DO NOT EDIT.
cask "mek-desktop" do
  arch arm: "arm64", intel: "amd64"

  version "$version"
  sha256 arm:   "$(sum arm64)",
         intel: "$(sum amd64)"

  url "https://github.com/prateep-r/mek/releases/download/v#{version}/mek-desktop_#{version}_darwin_#{arch}.zip"
  name "mek"
  desc "Desktop app for mek: cloud contexts, tunnels, resources and the audit log"
  homepage "https://github.com/prateep-r/mek"

  livecheck do
    skip "Auto-generated on release."
  end

  depends_on macos: ">= :ventura"

  app "mek.app"

  # The app isn't signed yet: without this, macOS refuses to open it.
  postflight do
    system_command "/usr/bin/xattr", args: ["-dr", "com.apple.quarantine", "#{appdir}/mek.app"]
  end

  zap trash: "~/Library/WebKit/io.github.prateep-r.mek"
end
CASK
